            <ui-select-choices repeat="imagen in $ctrl.imagenes | filter: {nombre: $select.search}"><img ng-src="{{$ctrl.perfilPath + imagen.nombre}}" style="width:25px; height:25px;"><small ng-bind-html="' ' + imagen.nombre | highlight: $select.search"></small></ui-select-choices>
          </ui-select>
