          <button type="button" ng-click="editarPublicacion(publicacion_actual)" aria-label="Editar publicidad" ng-if="USER.persona_id==publicacion_actual.persona_id" class="btn btn-default btn-sm item-menu" uib-tooltip="Editar" tooltip-placement="bottom" tooltip-append-to-body="true"><i class="fa fa-pencil"></i></button>
