        <div class="widget-buttons"><a href="" ng-init="minimizedUnidades = true" ng-click="minimizedUnidades = !minimizedUnidades"><i ng-class="{false: 'fa-minus', true: 'fa-plus'}[minimizedUnidades]" class="fa"></i></a><a href="" ng-click="openedUnidades=false"><i class="fa fa-times"></i></a></div>
